        // 文字列として比べると間違える
        System.out.println("文字列比較: " + "1.10.2".compareTo("1.2.10"));   // マイナス = 1.10.2 が小さい？
        System.out.println("正しい比較: " + compare("1.10.2", "1.2.10"));    // プラス = 1.10.2 が大きい

        System.out.println(compare("2.0.0", "2.0"));   // 0 = 同じ（足りない区画は 0 とみなす）
        System.out.println(compare("1.0.0", "1.0.1")); // マイナス
    }

    /** ドットで区切って、区画ごとに数値として比べる。 */
    static int compare(String a, String b) {
        String[] x = a.split("\\.");
        String[] y = b.split("\\.");
        int length = Math.max(x.length, y.length);
        for (int i = 0; i < length; i++) {
            int xi = i < x.length ? Integer.parseInt(x[i]) : 0;
            int yi = i < y.length ? Integer.parseInt(y[i]) : 0;
            if (xi != yi) {
                return Integer.compare(xi, yi);
            }
        }
        return 0;
    }
}

